import{_ as e,o,c as i,a5 as a}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"Low Level (RL Policy) — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/low-level.md","filePath":"software/sdk/cpp/low-level.md","lastUpdated":1787021357000}'),d={name:"software/sdk/cpp/low-level.md"};function s(r,t,n,l,c,h){return o(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="low-level-rl-policy-—-c-example" tabindex="-1">Low Level (RL Policy) — C++ Example <a class="header-anchor" href="#low-level-rl-policy-—-c-example" aria-label="Permalink to &quot;Low Level (RL Policy) — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_low_level.cpp</code></p><p>Low-level joint control example that subscribes to IMU, joystick, and leg-joint feedback topics, publishes joint position references and ownership commands, and optionally runs a <strong>learned walking policy (ONNX)</strong>.</p><h2 id="behavior-overview" tabindex="-1">Behavior overview <a class="header-anchor" href="#behavior-overview" aria-label="Permalink to &quot;Behavior overview&quot;">​</a></h2><p>The application has a single <strong>500 Hz control loop</strong> (2 ms period) and a keyboard-driven state machine with three states:</p><table tabindex="0"><thead><tr><th>State</th><th>Key</th><th>What the control loop does</th></tr></thead><tbody><tr><td><strong>Idle</strong></td><td>—</td><td>Tracks the stack&#39;s final reference (<code>rt/rbq/ref/motion/_0</code>) and republishes it — acts as a transparent pass-through</td></tr><tr><td><strong>Motion</strong></td><td><code>x</code> / <code>z</code></td><td>Interpolates joints to <code>ready</code> or <code>ground</code> postures using <code>JointControl</code> cosine trajectories</td></tr><tr><td><strong>Control</strong></td><td><code>c</code></td><td>Loads the ONNX policy, runs inference at <strong>100 Hz</strong> (decimation 5 of the 2 ms loop), publishes <code>MotionRef</code> with policy gains</td></tr></tbody></table><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li><strong>onnxruntime</strong> library — installed by <code>rbq_sdk/cpp/example/scripts/setup.bash</code>.</li><li>A policy directory containing <code>info.json</code> and <code>policy.onnx</code>.</li><li>Robot stack running (simulation or hardware).</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_low_level</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Requires root for RT thread; use without sudo for a normal thread</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">policyDi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Using pre-trained policy from rbq_simulator:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../rbq_simulator/rbq_gym/policy/rbq10/</span></span></code></pre></div><p>The application <strong>requires</strong> <code>-p</code>. Without it the program exits with an error.</p><h2 id="run-with-simulation" tabindex="-1">Run with simulation <a class="header-anchor" href="#run-with-simulation" aria-label="Permalink to &quot;Run with simulation&quot;">​</a></h2><ol><li>From <code>RBQ/</code>, start the full stack:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div></li><li>In RBQGUI: <strong>Connect</strong> → <strong>Auto Start Robot</strong> → <strong>Stance</strong> (<code>2</code>).</li><li>From <code>rbq_sdk/cpp/example/</code>:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../rbq_simulator/rbq_gym/policy/rbq10/</span></span></code></pre></div></li></ol><h2 id="keyboard-controls" tabindex="-1">Keyboard controls <a class="header-anchor" href="#keyboard-controls" aria-label="Permalink to &quot;Keyboard controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>q</code></td><td>Quit</td></tr><tr><td><code>z</code></td><td>Go to <strong>ground</strong> posture (folding → ground, ~4.8 s)</td></tr><tr><td><code>x</code></td><td>Go to <strong>ready</strong> posture (ground → folding → ready, ~2.8–5.6 s)</td></tr><tr><td><code>c</code></td><td>Start <strong>Walk / Control</strong> mode (loads policy from <code>-p</code>)</td></tr></tbody></table><p>Controls use raw terminal I/O (non-canonical, no echo) so each keypress is acted on immediately without pressing Enter.</p><h2 id="policy-directory" tabindex="-1">Policy directory <a class="header-anchor" href="#policy-directory" aria-label="Permalink to &quot;Policy directory&quot;">​</a></h2><p>The <code>-p</code> directory must contain:</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>info.json</code></td><td>Policy hyper-parameters (<code>run_name</code>, <code>policy_dt</code>, <code>action_scale</code>, stiffness/damping, observation/action sizes, normalization scales, default joint angles, command ranges)</td></tr><tr><td><code>policy.onnx</code></td><td>ONNX model exported from the training framework</td></tr></tbody></table><p>Supported policy names (from <code>info.json</code> <code>run_name</code>):</p><table tabindex="0"><thead><tr><th>Name</th><th>Observation vector</th><th>Notes</th></tr></thead><tbody><tr><td><code>rbq10</code></td><td>gyro, proj_grav, command, dof_pos, dof_vel, action</td><td>Single-frame</td></tr><tr><td><code>rbq10_trot</code></td><td>gyro, proj_grav, command, 4×dof_pos history (0,2,4,6), 4×dof_vel history, action×2, added_mass</td><td>7-frame history; decimation 5</td></tr><tr><td><code>rbq10_trot_run</code></td><td>Same as <code>rbq10_trot</code></td><td>Faster run variant</td></tr></tbody></table><h2 id="dds-topics" tabindex="-1">DDS topics <a class="header-anchor" href="#dds-topics" aria-label="Permalink to &quot;DDS topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Topic</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>Subscribe</td><td><code>rt/rbq/joy</code></td><td><code>Joy_</code></td><td>Joystick axes for velocity commands</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/imu</code></td><td><code>Imu_</code></td><td>Angular velocity + orientation quaternion</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/leg_joint</code></td><td><code>LegJointInfo_</code></td><td>Joint position and velocity (12 joints)</td></tr><tr><td>Subscribe</td><td><code>rt/rbq/ref/motion/_0</code></td><td><code>MotionRef_</code></td><td>Final blended reference (used in Idle)</td></tr><tr><td>Publish</td><td><code>rt/rbq/ref/motion/_20</code></td><td><code>MotionRef_</code></td><td>Joint position references with PD gains</td></tr><tr><td>Publish</td><td><code>rt/rbq/cmd/motion/owner/_20</code></td><td><code>JointOwnershipCmd_</code></td><td>Claim ownership of all 12 joints</td></tr></tbody></table><h2 id="joint-ordering" tabindex="-1">Joint ordering <a class="header-anchor" href="#joint-ordering" aria-label="Permalink to &quot;Joint ordering&quot;">​</a></h2><p>Joints are indexed 0–11 in the order:</p><p><code>HR</code> (hind-right): <code>HRR(0)</code>, <code>HRP(1)</code>, <code>HRK(2)</code> →<br><code>HL</code> (hind-left): <code>HLR(3)</code>, <code>HLP(4)</code>, <code>HLK(5)</code> →<br><code>FR</code> (front-right): <code>FRR(6)</code>, <code>FRP(7)</code>, <code>FRK(8)</code> →<br><code>FL</code> (front-left): <code>FLR(9)</code>, <code>FLP(10)</code>, <code>FLK(11)</code></p><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong>RT thread</strong>: When running as root, <code>rbq_sdk::Thread::generate_rt_thread</code> is used for SCHED_FIFO scheduling. Without root the example falls back to a standard <code>std::thread</code>.</li><li><strong>Ownership</strong>: <code>JointOwnershipCmd_</code> is published once when transitioning into Motion or Control state, claiming all 12 joints (<code>owner_20</code>). The stack respects ownership priority — the example has priority 20.</li><li><strong>Posture detection</strong>: <code>goToMotionReady()</code> checks the four hip-pitch angles against 60° to decide whether the robot is currently grounded (folded), and inserts a folding step if needed.</li><li><strong>Decimation</strong>: The policy runs every 5th control tick (100 Hz from a 500 Hz loop), matching the <code>policy_dt</code> in <code>info.json</code>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Likely cause</th></tr></thead><tbody><tr><td>No motion / topics silent</td><td>Stack not running or wrong network interface</td></tr><tr><td><code>Policy, PolicyParams not loaded</code></td><td><code>-p</code> path wrong, <code>info.json</code> missing/invalid, or <code>policy.onnx</code> missing</td></tr><tr><td><code>Thread deadline … over!</code></td><td>System too loaded for 2 ms period — run with sudo (RT thread) or reduce load</td></tr><tr><td><code>apt authentication errors</code></td><td>Unrelated host GPG issue; fix separately</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/software/sdk/cpp/overview.html">C++ SDK Overview</a></li><li><a href="/RBQ/nightly/software/concept.html">Concept — Low level / LV0</a></li></ul>`,37)])])}const u=e(d,[["render",s]]);export{b as __pageData,u as default};
